"""Native-spacecraft validation of in-house MHD, with no Parker remapping.

Run after simulations finish, e.g. python observations/analyze_native_model.py.
All paired observations occur on/after Nov25 (after normalization training).
Outputs: validation/inhouse_native.{json,tsv,png,pdf} under the project root.
"""
from __future__ import annotations

import argparse
import csv
import json
import time
from pathlib import Path

import numpy as np
from astropy.time import Time

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
FIELDS = {"density_cm3": ("density_cm3", "n_cm3", 4), "speed_km_s": ("speed_km_s", "speed_kms", 14), "flux_cm2_s": ("proton_flux_cm2_s", "flux_cm2_s", 15)}
MONITORS = {"wind": (1, "earth"), "stereo_a": (2, "stereoa"), "solar_orbiter": (3, "solo")}
CASE_PRIORITY = ("wide_fine", "wide_medium", "fine", "medium", "coarse", "wide_coarse")
NONPHYSICAL_EXPORT_CASES = {"wide_movie", "pilot", "interrupted_wide_medium"}


def metric(o, p):
    mask = np.isfinite(o) & np.isfinite(p) & (o > 0) & (p > 0)
    o, p = np.asarray(o)[mask], np.asarray(p)[mask]
    if len(o) < 2:
        return {"samples": len(o)}
    return {"samples": len(o), "observed_median": float(np.median(o)), "model_median": float(np.median(p)), "median_model_over_observed": float(np.median(p/o)), "observed_over_model_p16_50_84": np.percentile(o/p,[16,50,84]).tolist(), "observed_minus_model_p16_50_84": np.percentile(o-p,[16,50,84]).tolist(), "median_absolute_fractional_error": float(np.median(abs(p/o-1))), "rmse": float(np.sqrt(np.mean((p-o)**2))), "pearson_r": float(np.corrcoef(o,p)[0,1]), "log_pearson_r": float(np.corrcoef(np.log(o),np.log(p))[0,1]), "rms_log_ratio": float(np.sqrt(np.mean(np.log(p/o)**2)))}


def average_at_native(stamps, native_monitor, times, values):
    """Mean model over each native hour, rejecting extrapolation or large gaps."""
    base = stamps - (0.5/24 if native_monitor == "wind" else 0)
    quadrature = base[:,None] + np.linspace(0,1/24,61)[None,:]
    valid = (quadrature[:,0] >= times.min()) & (quadrature[:,-1] <= times.max())
    # Probe output is hourly; a missing sample must not silently bridge >90min.
    gaps = np.flatnonzero(np.diff(times) > 1.5/24)
    for gap in gaps:
        valid &= (quadrature[:,-1] <= times[gap]) | (quadrature[:,0] >= times[gap+1])
    result = np.full(len(stamps), np.nan)
    if np.any(valid):
        result[valid] = np.trapezoid(np.interp(quadrature[valid],times,values),dx=1/60,axis=1)
    return result


def load_probes(path, origin):
    if not path.exists():
        return None
    with path.open() as f:
        rows = list(csv.DictReader(f))
    if not rows:
        return None
    ans = {}
    for name,(number,target) in MONITORS.items():
        selected = [r for r in rows if int(r["probe_id"]) == number]
        if not selected:
            continue
        timecol = "day" if "day" in selected[0] else "tday"
        time = np.array([float(r[timecol])+origin for r in selected])
        order = np.argsort(time)
        time = time[order]
        if np.any(np.diff(time) <= 0):
            raise RuntimeError(f"Nonunique probe times: {path} {name}")
        ans[name] = {"mjd":time,**{field:np.array([float(r[spec[1]]) for r in selected])[order] for field,spec in FIELDS.items()}}
    return ans


def make_plot(records, preferred_case, output):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import matplotlib.dates as mdates
    colors = {"inhouse":"#D55E00", "ccmc":"#0072B2", "observed":"#20242A"}
    fig, axes = plt.subplots(3,3,figsize=(14,9),sharex=True,constrained_layout=True)
    titles = {"wind":"Wind / OMNI (held out)","stereo_a":"STEREO-A","solar_orbiter":"Solar Orbiter"}
    labels = {"density_cm3":"Proton density (cm$^{-3}$)","speed_km_s":"Speed (km s$^{-1}$)","flux_cm2_s":"Proton flux (cm$^{-2}$ s$^{-1}$)"}
    for i,name in enumerate(MONITORS):
        use = [r for r in records if r["case"] == preferred_case and r["monitor"] == name]
        if not use:
            continue
        t=Time([r["mjd_utc"] for r in use],format="mjd",scale="utc").to_datetime()
        for j,field in enumerate(FIELDS):
            ax=axes[i,j]
            ax.plot(t,[r["observed_"+field] for r in use],".",color=colors["observed"],markersize=2.5,label="Measured")
            ax.plot(t,[r["inhouse_"+field] for r in use],color=colors["inhouse"],lw=1.4,label="In-house MHD ("+preferred_case+")")
            ax.plot(t,[r["ccmc_ambient_"+field] for r in use],color=colors["ccmc"],lw=1.1,alpha=.9,label="CCMC ambient")
            ax.set_ylabel(labels[field]);ax.grid(alpha=.22)
            if j != 1:
                ax.set_yscale("log")
            if i==0:
                ax.set_title(labels[field].split(" (")[0])
            if j==0:
                ax.text(.02,.96,titles[name],transform=ax.transAxes,ha="left",va="top",fontsize=9,fontweight="bold")
            ax.xaxis.set_major_locator(mdates.DayLocator(interval=2))
            ax.xaxis.set_major_formatter(mdates.DateFormatter("%b %d"))
    axes[0,1].legend(loc="upper right",fontsize=7)
    for ax in axes[-1]:ax.set_xlabel("2025 UTC, after normalization training")
    fig.suptitle("Native spacecraft validation: no Parker remapping or time-shift fitting",fontsize=13)
    fig.savefig(output/"inhouse_native.png",dpi=170)
    fig.savefig(output/"inhouse_native.pdf")
    plt.close(fig)


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument("--cases",nargs="+",default=list(CASE_PRIORITY))
    parser.add_argument("--output-dir",type=Path,default=ROOT/"validation")
    parser.add_argument("--no-plot",action="store_true")
    parser.add_argument("--wait-for-case",help="Wait for this run's statistics.json before validating; poll every15s")
    parser.add_argument("--wait-timeout-seconds",type=float,default=900)
    args=parser.parse_args()
    if args.wait_for_case:
        deadline=time.monotonic()+args.wait_timeout_seconds
        marker=ROOT/f"results/{args.wait_for_case}/statistics.json"
        print("Waiting for",marker,flush=True)
        while not marker.exists():
            if time.monotonic()>deadline:
                raise SystemExit("Timed out waiting for completed run: "+args.wait_for_case)
            time.sleep(15)
    metadata=json.loads((ROOT/"inputs/metadata.json").read_text())
    origin=float(metadata["origin_mjd_utc"])
    requested_start,requested_stop=Time(["2025-11-25T00:00:00","2025-12-06T00:00:00"],format="isot",scale="utc").mjd
    training_stop=Time(metadata["calibration_interval_utc"][1],format="isot",scale="utc").mjd
    assert requested_start>=training_stop,"Validation would overlap normalization training"
    ccmc=np.load(ROOT/"external_model/ccmc_profiles.npz")
    probes={case:load_probes(ROOT/f"results/{case}/probe.csv",origin) for case in args.cases if case not in NONPHYSICAL_EXPORT_CASES and (ROOT/f"results/{case}/statistics.json").exists()}
    probes={k:v for k,v in probes.items() if v}
    if not probes:
        raise SystemExit("No populated probe.csv available yet; run simulations first.")
    preferred_case=next((case for case in CASE_PRIORITY if case in probes),next(iter(probes)))
    report={"requested_interval_start_utc":"2025-11-25T00:00:00", "requested_stop_exclusive_utc":"2025-12-06T00:00:00", "actual_coverage":"Per instrument/case coverage below; no extrapolation outside completed probe times.", "normalization_metadata":metadata, "validation_training_separation":"All native paired samples at or after the exclusive normalization training stop. Wind is entirely absent from normalization training.", "frame":"Native spacecraft positions; no corotation or radial propagation applied to observations.", "cadence":"Model native hourly means: COHO [timestamp,timestamp+1h]; OMNI [timestamp-0.5h,timestamp+0.5h], 1-minute trapezoid quadrature. In-house probe series interpolated between hourly outputs; CCMC between native approximately3.6-minute output.", "caveats":["Hourly in-house probe cadence smooths unresolved subhour variability.","STEREO-A/Solar Orbiter post-training samples provide temporal validation, while Wind supplies independent-instrument validation.","The boundary solar maps are retrospective; this is a hindcast and not an operational forecast.","Results are not calibrated to the comet or to CCMC output; residual errors constrain representativeness of the solar-wind estimate."],"cases":{}}
    report["chart_reference_case"]=preferred_case
    report["chart_case_priority"]=list(CASE_PRIORITY)
    report["excluded_export_cases"]=sorted(NONPHYSICAL_EXPORT_CASES)
    records=[]
    for case,by_monitor in probes.items():
        report["cases"][case]={}
        for monitor,(number,target) in MONITORS.items():
            if monitor not in by_monitor:continue
            obsrows=list(csv.DictReader((HERE/f"plasma_{monitor}.tsv").open(),delimiter="\t"))
            obsrows=[r for r in obsrows if requested_start<=float(r["mjd_utc"])<requested_stop]
            stamps=np.array([float(r["mjd_utc"]) for r in obsrows])
            obs={field:np.array([float(r[spec[0]]) for r in obsrows]) for field,spec in FIELDS.items()}
            model=by_monitor[monitor]
            own={field:average_at_native(stamps,monitor,model["mjd"],model[field]) for field in FIELDS}
            others={}
            for version,desc in [("1","cme"),("2amb","ambient")]:
                track=ccmc[target+version]
                others[desc]={field:average_at_native(stamps,monitor,track[:,0],track[:,spec[2]]) for field,spec in FIELDS.items()}
            paired=np.ones(len(stamps),dtype=bool)
            for field in FIELDS:paired &= np.isfinite(own[field]) & np.isfinite(others["ambient"][field]) & np.isfinite(others["cme"][field])
            result={"samples":int(paired.sum()), "discarded_outside_model_coverage_or_missing":int((~paired).sum())}
            if np.any(paired):
                result.update(first_paired_utc=Time(stamps[paired].min(),format="mjd").isot,last_paired_utc=Time(stamps[paired].max(),format="mjd").isot)
            result["inhouse"]={field:metric(obs[field][paired],own[field][paired]) for field in FIELDS}
            result["ccmc_ambient"]={field:metric(obs[field][paired],others["ambient"][field][paired]) for field in FIELDS}
            result["ccmc_cme"]={field:metric(obs[field][paired],others["cme"][field][paired]) for field in FIELDS}
            report["cases"][case][monitor]=result
            for k,t in enumerate(stamps):
                if not paired[k]:continue
                row={"case":case,"monitor":monitor,"mjd_utc":t,"utc":Time(t,format="mjd").isot}
                for field in FIELDS:
                    row.update({"observed_"+field:obs[field][k],"inhouse_"+field:own[field][k],"ccmc_ambient_"+field:others["ambient"][field][k],"ccmc_cme_"+field:others["cme"][field][k]})
                records.append(row)
    args.output_dir.mkdir(exist_ok=True,parents=True)
    if not records:
        raise SystemExit("Probe files exist but no complete post-training native hour is covered yet.")
    (args.output_dir/"inhouse_native.json").write_text(json.dumps(report,indent=2,allow_nan=False)+"\n")
    with (args.output_dir/"inhouse_native.tsv").open("w",newline="") as f:
        w=csv.DictWriter(f,list(records[0]),delimiter="\t");w.writeheader();w.writerows(records)
    if not args.no_plot:
        make_plot(records,preferred_case,args.output_dir)
    print(json.dumps({case:{name:{"samples":d["samples"],"flux_median_model_over_obs":d["inhouse"]["flux_cm2_s"].get("median_model_over_observed"),"flux_r":d["inhouse"]["flux_cm2_s"].get("pearson_r")} for name,d in content.items()} for case,content in report["cases"].items()},indent=2))


if __name__=="__main__":main()
#!/usr/bin/env python3
"""Independent STA stream timing context from this project's frozen observations.

No sibling-model numerical output is used. Ballistic mapping is contextual and
multivalued where streams overtake; it is not an MHD solution or a fitted shift.
"""
from pathlib import Path
import csv
import datetime as dt
import hashlib
import json

import numpy as np
from astropy.time import Time

HERE=Path(__file__).resolve().parent
ROOT=HERE.parent
OMEGA=14.1844
AU_KM=149597870.7
ORIGIN=60980.


def read(path, sep="\t"):
    return np.genfromtxt(path,names=True,delimiter=sep,dtype=None,encoding="utf8")


def utc(t):
    return Time(float(t),format="mjd",scale="utc").isot


def quant(x):
    return {k:float(v) for k,v in zip(["min","p16","median","p84","max"],np.percentile(x,[0,16,50,84,100]))}


def at(track,t,key):
    t=np.asarray(t)
    assert t.min()>=track["mjd_utc"][0] and t.max()<=track["mjd_utc"][-1]
    return np.interp(t,track["mjd_utc"],track[key])


def mapped(source_t,speed,monitor,comet,longitude="solar_equatorial_longitude_deg"):
    source_t=np.asarray(source_t,float);speed=np.broadcast_to(speed,source_t.shape)
    rs=at(monitor,source_t,"radius_au");ps=at(monitor,source_t,longitude)
    arrival=source_t.copy()
    for _ in range(30):
        rc=at(comet,arrival,"radius_au");pc=at(comet,arrival,longitude)
        rotation=((pc-ps+180)%360-180)/OMEGA
        radial=(rc-rs)*AU_KM/speed/86400
        updated=source_t+rotation+radial
        if np.max(abs(updated-arrival))<1e-10:break
        arrival=updated
    return updated,rotation,radial,rs/at(comet,updated,"radius_au"),ps,at(comet,updated,longitude)


def first_sustained(t,v,threshold,lo,hi):
    # Three consecutive native hourly samples; no optimized phase/smoothing.
    for j in range(len(t)-2):
        if lo<=t[j]<hi and np.max(np.diff(t[j:j+3]))<=1.01/24 and np.all(v[j:j+3]>=threshold):
            return float(t[j])
    return None


def main():
    source_path=HERE/"raw/original_stereo_a.csv"
    raw=list(csv.reader(source_path.open()))
    sample=[]
    for row in raw:
        try:v,n=map(float,row[1:])
        except ValueError:continue
        if .01<n<500 and 100<v<1500:sample.append((Time(row[0],format="isot",scale="utc").mjd,v,n))
    sample=np.array(sample);stamp,v,n=sample.T
    # COHO labels interval starts. Use hour centers, and report the half-hour ambiguity.
    time=stamp+.5/24
    supplementary=read(HERE/"plasma_stereo_a.tsv")
    b=np.interp(stamp,supplementary["mjd_utc"],supplementary["B_magnitude_nT"])
    temp=np.interp(stamp,supplementary["mjd_utc"],supplementary["temperature_K"])
    monitor=read(HERE/"ephemeris_stereo_a.tsv");comet=read(HERE/"ephemeris_comet.tsv")
    lo,hi=Time(["2025-11-26","2025-12-01"]).mjd
    use=(time>=lo)&(time<hi)
    time,stamp,v,n,b,temp=[x[use] for x in [time,stamp,v,n,b,temp]]
    arrival,rotation,radial,ratio,source_lon,target_lon=mapped(time,v,monitor,comet)
    ecliptic_arrival,*_=mapped(time,v,monitor,comet,"ecliptic_longitude_deg")
    records=[]
    for j,t in enumerate(time):
        records.append({"source_interval_start_utc":utc(stamp[j]),"source_center_utc":utc(t),"source_center_mjd":float(t),"speed_km_s":float(v[j]),"density_cm3":float(n[j]),"B_magnitude_nT":float(b[j]),"temperature_K":float(temp[j]),"source_solar_longitude_deg":float(source_lon[j]),"target_solar_longitude_deg":float(target_lon[j]),"rotation_delay_days":float(rotation[j]),"radial_delay_days":float(radial[j]),"arrival_utc":utc(arrival[j]),"arrival_mjd":float(arrival[j]),"r2_scaled_density_cm3":float(n[j]*ratio[j]**2),"r2_scaled_flux_cm2_s":float(n[j]*ratio[j]**2*v[j]*1e5)})
    with (HERE/"stereo_stream_timing.tsv").open("w",newline="") as f:
        writer=csv.DictWriter(f,list(records[0]),delimiter="\t");writer.writeheader();writer.writerows(records)
    peak_n=int(np.argmax(n));peak_b=int(np.argmax(b));peak_v=int(np.argmax(v))
    feature_rows={"density_peak":records[peak_n],"B_peak":records[peak_b],"speed_peak":records[peak_v]}
    for threshold in [500,600,650]:
        first=first_sustained(time,v,threshold,lo,hi)
        if first is not None:
            j=int(np.argmin(abs(time-first)));feature_rows[f"first_sustained_{threshold}kms"]=records[j]
    fast=v>=600;dense=(n>=10)&(v<600)
    subsets={}
    window_start,window_stop=Time(["2025-12-03T12:37:38","2025-12-04T17:22:29"]).mjd
    fast_during_xmm=fast&(arrival>=window_start)&(arrival<=window_stop)
    for label,selection in [("fast_v_ge_600",fast),("dense_n_ge_10_v_lt_600",dense),("fast_mapped_inside_published_xmm",fast_during_xmm)]:
        subsets[label]={"samples":int(selection.sum()),"source_first_utc":utc(time[selection].min()),"source_last_utc":utc(time[selection].max()),"arrival_first_utc":utc(arrival[selection].min()),"arrival_last_utc":utc(arrival[selection].max()),"source_speed_km_s":quant(v[selection]),"source_density_cm3":quant(n[selection]),"source_B_nT":quant(b[selection]),"source_temperature_K":quant(temp[selection]),"r2_density_at_comet_cm3":quant((n*ratio**2)[selection])}
    # Explicitly retain folding: sorting and joining arrivals would conceal it.
    folds=int(np.sum(np.diff(arrival)<0))
    case=json.loads((ROOT/"results/summary.json").read_text())["reference_case"]
    probes=read(ROOT/f"results/{case}/probe.csv",",")
    models={}
    for ident,label in [(2,"stereo_a"),(0,"comet")]:
        a=probes[probes["probe_id"]==ident];t=a["day"]+ORIGIN
        start,stop=Time(["2025-11-26","2025-12-02"] if ident==2 else ["2025-12-01","2025-12-05"]).mjd
        selected=(t>=start)&(t<stop);aa=a[selected];tt=t[selected]
        model={"interval_start_utc":utc(start),"interval_stop_exclusive_utc":utc(stop),"density_peak_utc":utc(tt[np.argmax(aa["n_cm3"])]),"density_peak_cm3":float(aa["n_cm3"].max()),"speed_peak_utc":utc(tt[np.argmax(aa["speed_kms"])]),"speed_peak_km_s":float(aa["speed_kms"].max()),"speed_crossings_utc":{}}
        for threshold in [500,550,600,650,700]:
            above=np.flatnonzero(aa["speed_kms"]>=threshold)
            model["speed_crossings_utc"][str(threshold)]=utc(tt[above[0]]) if len(above) else None
        models[label]=model
    same=[{"earlier_source_utc":utc(time[j]),"later_source_utc":utc(time[j+1]),"earlier_arrival_utc":utc(arrival[j]),"later_arrival_utc":utc(arrival[j+1])} for j in np.flatnonzero(np.diff(arrival)<0)]
    out={"author":"Codex-observations","created_utc":dt.datetime.now(dt.timezone.utc).isoformat(),"source":"Our frozen original STA density/speed cache; supplementary B,T from our independently archived HAPI request. No sibling-model numerical output reused.","source_cache_sha256":hashlib.sha256(source_path.read_bytes()).hexdigest(),"time_convention":"COHO interval-start timestamp shifted+0.5h to represent hourly mean center; using the label instead changes timing by approximately half an hour.","coordinate_frame":"Sun-centered fixed solar-equatorial inertial longitude from full geometric JPL Horizons states; same rotation sign as original study.","mapping_equation":"ta=ts+wrap180(phi_comet(ta)-phi_STA(ts))/14.1844+(r_comet(ta)-r_STA(ts))*AU/v; iteration uses evolving comet position, not fixed observation-epoch separation.","no_fitted_phase_or_speed_correction":True,"limitations":["Assumes a persistent corotating stream band, not that one parcel moves sideways from STA to the comet.","Mapping preserves measured speed and applies only geometric inverse-square dilution; it omits compression, acceleration, transverse transport and transient evolution.","Folded arrival times reveal overtaking; the mapped samples must not be joined into a single-valued physical prediction.","n,B,T signatures support an SIR-like compression followed by a high-speed stream, but alone do not uniquely distinguish a pure SIR from transient contributions.","This is contextual timing evidence, not a fitted phase shift, a replacement for3D MHD, or an independent validation of comet density."],"features":feature_rows,"subsets":subsets,"negative_adjacent_arrival_differences":folds,"fold_examples":same[:6],"maximum_solar_vs_ecliptic_arrival_difference_hours":float(np.max(abs(arrival-ecliptic_arrival))*24),"prototype_reference_case":case,"prototype_transitions":models}
    out["prototype_probe_sha256"]=hashlib.sha256((ROOT/f"results/{case}/probe.csv").read_bytes()).hexdigest()
    out["ephemeris_files"]=["ephemeris_stereo_a.tsv","ephemeris_comet.tsv"]
    (HERE/"stereo_stream_timing.json").write_text(json.dumps(out,indent=2)+"\n")
    plot(time,v,n,b,arrival,ratio,probes,case)
    print(json.dumps({"features":{k:{z:row[z] for z in ["source_center_utc","speed_km_s","arrival_utc","r2_scaled_density_cm3"]} for k,row in feature_rows.items()},"subsets":subsets,"folds":folds,"models":models},indent=2))


def plot(time,v,n,b,arrival,ratio,probes,case):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import matplotlib.dates as dates
